WITH base AS (SELECT *, UPPER(product_name) AS product_name_upper, COALESCE(brand, 'OTHER') AS brand_filled FROM products WHERE launch_date > DATE '2023-06-25'), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY launch_date NULLS LAST, id) AS rank_in_group FROM base QUALIFY rank_in_group = 1), cleaned AS (SELECT id, price, cost, launch_date, supplier_id, product_name_upper, brand_filled, rank_in_group, FLOOR(stock_qty) AS stock_qty_whole, CASE WHEN brand IN ('Acme', 'Umbrella') THEN 'Tier 1' ELSE 'Other' END AS brand_group FROM ranked WHERE rank_in_group <= 1), enriched AS (SELECT id, price, cost, launch_date, supplier_id, product_name_upper, brand_filled, rank_in_group, stock_qty_whole, brand_group, RANK() OVER (ORDER BY cost DESC NULLS FIRST) AS cost_rank, LAST_VALUE(cost, TRUE) OVER (ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY stock_qty_whole DESC, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY price, id) AS seq_no_2, NTILE(3) OVER (PARTITION BY supplier_id ORDER BY cost DESC, id) AS cost_bucket FROM cleaned), ranked_products AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY rank_in_group DESC, id) = 1) SELECT id, price, supplier_id, brand_filled, stock_qty_whole, brand_group, cost_rank, last_known_cost, seq_no_2 FROM ranked_products ORDER BY cost_rank NULLS LAST;
